367	  });
368	
369	  for (let attempt = 1; attempt <= UPSTREAM_RECONNECT_ATTEMPTS; attempt += 1) {
370	    if (session.closing || session.generation !== generation || !isWebSocketOpen(downstreamWs)) {
371	      session.retryTask = null;
372	      config.statusTracker?.recordReconnect({
373	        active: false,
374	        attempts: attempt - 1,
375	      });
376	      return;
377	    }
