382	      const result = await client.request("thread/resume", resumeParams);
383	      assertResumeResultMatchesRequestedThread(result, resumeParams.threadId);
384	      if (!isSessionActive(session, downstreamWs, generation)) {
385	        client.close();
386	        session.retryTask = null;
387	        return;
388	      }
389	      session.upstream = client;
390	      session.retryTask = null;
391	      config.statusTracker?.recordReconnect({
